function readProfileAuthority(e){return prepareProfileAuthorityRead(e)()}function prepareProfileAuthorityRead(e){const t=new Int32Array(e.generation);const n=new BigInt64Array(e.lifetime.revision);const r=e.entries.map(e=>({cell:new Int32Array(e.state),revision:e.revision}));return()=>{if(Atomics.load(n,0)!==e.lifetime.epoch||Atomics.load(t,0)!==1)return`revoked`;const i=Atomics.load(t,1);if(i%2!==0)return`pending`;let a=`current`;for(const{cell:e,revision:t}of r){const n=Atomics.load(e,0);const r=Atomics.load(e,1);if(t!==void 0&&n!==t)a=`revoked`;else if(r===2&&a!==`revoked`)a=`uncertain`;else if(r===1&&a===`current`)a=`pending`;else if(r!==0&&r!==1&&r!==2)a=`revoked`}if(Atomics.load(n,0)!==e.lifetime.epoch||Atomics.load(t,0)!==1)return`revoked`;return Atomics.load(t,1)===i?a:`pending`}}export{readProfileAuthority as n,prepareProfileAuthorityRead as t};